import type { BeliefState, Position } from "../domain.js";
import type { AgentCapability } from "./contracts.js";

export const explorationModule: AgentCapability = {
  id: "exploration",
  version: 1,
  purpose: "Improve task selection and navigation through balanced exploration and exploitation.",
};

export function explore(state: BeliefState, from: Position): Position | undefined {
  const nearbyPositions = getNearbyPositions(from);
  const unvisitedPositions = nearbyPositions.filter((position) => !state.visitedPositions.has(position));
  if (unvisitedPositions.length > 0) {
    return unvisitedPositions[0];
  }
  return undefined;
}

function getNearbyPositions(from: Position): Position[] {
  const nearbyPositions: Position[] = [];
  for (const direction of [{ x: -1, y: 0 }, { x: 1, y: 0 }, { x: 0, y: -1 }, { x: 0, y: 1 }]) {
    const position = { x: from.x + direction.x, y: from.y + direction.y };
    nearbyPositions.push(position);
  }
  return nearbyPositions;
}

